assert len(drafts) == len(sources) == 24
answer = [drafts[s['number']] for s in sources]
for item in answer:
    key = item['code_id'] + '|' + item['source_id']
    required = references['requirements'].get(key, [])
    actual = item.get('reference_checks', [])
    assert {c['target_key'] for c in actual} == set(required), item['number']
    assert len(actual) == len(required), item['number']
    for check in actual:
        assert check['view_sha256'] == references['targets'][check['target_key']]['view_sha256']
        assert len(check['assessment']) >= 80
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
